"""Constructor-based circle packing for n=26 circles (proxy + LP polish)"""
import numpy as np
from scipy.optimize import linprog, minimize


def _solve_radii(centers):
    """Maximize sum of radii for fixed centers via LP (robust, exact)."""
    centers = np.asarray(centers, dtype=float)
    n = len(centers)
    c = -np.ones(n)
    A_rows = []
    b_vals = []
    for i in range(n):
        for j in range(i + 1, n):
            d = float(np.hypot(centers[i, 0] - centers[j, 0],
                               centers[i, 1] - centers[j, 1]))
            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(min(x, y, 1.0 - x, 1.0 - y))
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0.0)
    r = np.array([min(x, y, 1.0 - x, 1.0 - y) for x, y in centers])
    D = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            d = float(np.hypot(centers[i, 0] - centers[j, 0],
                               centers[i, 1] - centers[j, 1]))
            D[i, j] = D[j, i] = d
    for _ in range(3000):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                s = r[i] + r[j]
                d = D[i, j]
                if s > d + 1e-12:
                    if s <= 0:
                        r[i] = r[j] = 0.0
                        continue
                    t = d / s
                    r[i] *= t
                    r[j] *= t
                    changed = True
        if not changed:
            break
    return r


def _hex_centers(spacing):
    dy = spacing * np.sqrt(3) / 2
    pts = []
    row = 0
    y = spacing
    while y <= 1.0 - spacing:
        x_offset = (spacing / 2) if (row % 2 == 1) else 0.0
        x = spacing + x_offset
        while x <= 1.0 - spacing:
            pts.append([x, y])
            x += spacing
        y += dy
        row += 1
    pts = np.array(pts)
    if len(pts) < 26:
        return None
    dists = np.sqrt((pts[:, 0] - 0.5) ** 2 + (pts[:, 1] - 0.5) ** 2)
    idx = np.argsort(dists)
    return pts[idx[:26]].copy()


def _fast_objective(x):
    c = x.reshape(26, 2)
    n = 26
    walls = np.minimum(np.minimum(c[:, 0], c[:, 1]),
                       np.minimum(1.0 - c[:, 0], 1.0 - c[:, 1]))
    vals = walls.copy()
    for i in range(n):
        for j in range(i + 1, n):
            d = float(np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1]))
            half = 0.5 * d
            if half < vals[i]:
                vals[i] = half
            if half < vals[j]:
                vals[j] = half
    return -float(np.sum(vals))


def _lp_objective(x):
    return -float(np.sum(_solve_radii(x.reshape(26, 2))))


def construct_packing():
    n = 26
    inits = []
    for sp in [0.16, 0.18, 0.20]:
        c = _hex_centers(sp)
        if c is not None:
            inits.append(c)
    gg = [0.13, 0.28, 0.5, 0.72, 0.87]
    cb = []
    for x in gg:
        for y in gg:
            if abs(x - 0.5) < 1e-9 and abs(y - 0.5) < 1e-9:
                continue
            cb.append([x, y])
    cb.append([0.5, 0.205])
    cb.append([0.5, 0.795])
    inits.append(np.array(cb)[:26])

    # Phase 1: fast proxy optimization from each init
    candidates = []
    for init in inits:
        result = minimize(
            _fast_objective, init.flatten(), method='L-BFGS-B',
            bounds=[(0.02, 0.98)] * 52,
            options={'maxiter': 150, 'ftol': 1e-10}
        )
        candidates.append(result.x.reshape(26, 2))

    # Phase 2: short LP-polish on the 3 best candidates (by proxy score)
    candidates.sort(key=lambda cc: _fast_objective(cc.flatten()))
    best_centers = None
    best_sum = -1.0
    for cc in candidates[:3]:
        result = minimize(
            _lp_objective, cc.flatten(), method='L-BFGS-B',
            bounds=[(0.02, 0.98)] * 52,
            options={'maxiter': 40, 'ftol': 1e-9}
        )
        opt_centers = result.x.reshape(26, 2)
        s = float(np.sum(_solve_radii(opt_centers)))
        if s > best_sum:
            best_sum = s
            best_centers = opt_centers.copy()

    radii = _solve_radii(best_centers)
    return best_centers, radii, float(np.sum(radii))

